"""Central estática dos quatro painéis; não consulta nem altera o banco."""
from pathlib import Path
HTML = r'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Central de Painéis · Log-PI</title><style>
*{box-sizing:border-box}body{margin:0;background:#091724;color:#eaf3f9;font:15px system-ui,sans-serif}header{padding:20px 24px;border-bottom:1px solid #304b60}small{color:#45d6be}h1{margin:4px 0;font-size:24px}p{color:#b5cad8}nav{display:flex;gap:8px;flex-wrap:wrap;padding:14px 24px}button,a{font:inherit}button{background:#142e40;border:1px solid #486176;color:#eaf3f9;padding:12px 16px;border-radius:8px;cursor:pointer}button[aria-pressed=true]{background:#126e65;border-color:#45d6be}button:focus-visible,a:focus-visible{outline:3px solid #ffc36b;outline-offset:3px}.toolbar{padding:0 24px 12px;display:flex;gap:16px;align-items:center;flex-wrap:wrap}.toolbar a{color:#61dcca}iframe{display:block;border:0;width:100%;height:calc(100dvh - 230px);min-height:480px;background:#fff}#welcome{padding:40px 24px;max-width:900px}#welcome h2{font-size:30px}.note{font-size:13px} [hidden]{display:none!important}@media(max-width:600px){header,nav{padding:14px}button{flex:1 1 40%}.toolbar{padding:0 14px 12px}iframe{height:75dvh}}
</style></head><body><header><small>LOG-PI / CONTROL TOWER</small><h1>Central de Painéis</h1><p>Monitoramento, contratos, abastecimento, rastreamento e manutenção em um só lugar.</p></header><nav aria-label="Escolher painel"><button data-panel="monitoramento" aria-pressed="false">Central de Monitoramento</button><button data-panel="contratos" aria-pressed="false">Contratos e rotas</button><button data-panel="abastecimento" aria-pressed="false">Abastecimento</button><button data-panel="rastreamento" aria-pressed="false">Frota e rastreamento</button><button data-panel="manutencao" aria-pressed="false">Frota e manutenção</button></nav><div id="welcome"><h2>Qual análise você quer abrir?</h2><p>Selecione um dos painéis acima. A navegação continua disponível para alternar entre as análises.</p><p class="note">Cada painel informa sua própria data de referência. A central reúne os acessos e não altera os cálculos.</p></div><div class="toolbar" id="toolbar" hidden><strong id="current"></strong><a id="direct" target="_blank" rel="noopener">Abrir painel em outra aba</a><span id="loading" role="status"></span></div><iframe id="panel" title="Painel selecionado" hidden></iframe><script>
const panels={monitoramento:['Central de Monitoramento','../monitoramento/'],contratos:['Contratos e rotas','../'],abastecimento:['Abastecimento','../abastecimento/'],rastreamento:['Frota e rastreamento','../rastreamento/'],manutencao:['Frota e manutenção','../manutencao/']};
function openPanel(key){if(!panels[key])return;const [name,url]=panels[key];document.querySelectorAll('[data-panel]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.panel===key)));document.getElementById('welcome').hidden=true;document.getElementById('toolbar').hidden=false;document.getElementById('current').textContent=name;document.getElementById('direct').href=url;document.getElementById('loading').textContent='Carregando painel…';const frame=document.getElementById('panel');frame.hidden=false;frame.title=name;frame.src=url;history.replaceState(null,'','#'+key);}
document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>openPanel(b.dataset.panel));document.getElementById('panel').onload=()=>document.getElementById('loading').textContent='';openPanel(location.hash.slice(1));
</script></body></html>'''
if __name__ == '__main__':
    output=Path('public/central/index.html');output.parent.mkdir(parents=True,exist_ok=True);output.write_text(HTML,encoding='utf-8');print('Central gerada: public/central/index.html')
